#[summary("token-bucket rate limiter: refill whole periods, then accept requests while a token is available")]
mod tasks {
    spec fn lim_domain(times: &[i64], cap: i64, every: i64) -> bool {
        cap >= 0 && every >= 1 && lim_ok(times)
    }

    spec fn lim_ok(times: &[i64]) -> bool {
        forall|i: usize| #[trigger] i < times.len() ==> times[i] >= 0 && (i == 0 || times[i - 1] <= times[i])
    }

    spec fn lim_post(times: &[i64], r: i64) -> bool {
        0 <= r && r <= times.len()
    }

    #[effects(io)]
    #[uses(lim_domain, lim_ok, lim_post)]
    fn limiter(times: &[i64], cap: i64, every: i64) -> (r: i64)
        requires lim_domain(times, cap, every),
        ensures lim_post(times, r),
    {
        let mut tok: i64 = cap;
        let mut mark: i64 = 0;
        let mut acc: i64 = 0;
        let mut i: usize = 0;
        while i < times.len()
            invariant 0 <= i, i <= times.len(), 0 <= tok, tok <= cap, 0 <= mark, mark <= times.len(), i < times.len() ==> mark <= times[i], 0 <= acc, acc <= i,
            decreases times.len() - i,
        {
            let dt: i64 = times[i] - mark;
            let g: i64 = dt / every;
            assert(0 <= g);
            assert(g * every <= dt);
            if g >= cap - tok {
                tok = cap;
            } else {
                tok = tok + g;
            }
            assert(0 <= tok);
            assert(tok <= cap);
            mark = mark + g * every;
            assert(mark <= times[i]);
            if tok >= 1 {
                tok = tok - 1;
                acc = acc + 1;
                print_i64(1);
            } else {
                print_i64(0);
            }
            assert(0 <= tok);
            assert(tok <= cap);
            i = i + 1;
        }
        acc
    }
}

