#[summary("dialect probe")]
mod probe {
    #[effects(pure)]
    #[uses(sq)]
    fn cast(x: i64) -> i64
        requires nonneg(x),
    {
        let t: usize = usize::try_from(x).unwrap();
        assert(t <= 10);
        assert(sq(0));
        x + 1
    }

    #[effects(io)]
    fn main() -> () {
        let _a: i64 = cast(1);
        p(1);
    }

    spec fn nonneg(x: i64) -> bool {
        x >= 0
    }

    #[effects(io)]
    fn p(x: i64) -> () {
        print_i64(x);
        print_i64(2);
    }

    spec fn sq(x: i64) -> bool {
        x * x == 0
    }
}
